-- Batch 05 — targeted quality pass of essential dignity, sect and place terminology.
-- Direct passages inspected: al-Biruni Book of Instruction §§443,445; Lilly Christian Astrology I pp.103,112-113.
-- Source-specific witness attributions. No formula tables, schemes, aliases, ontological terms or existing historical accounts changed.
PRAGMA foreign_keys=ON;

UPDATE term_article_sections SET heading='Sources of accidental strength and weakness',body='Angularity, motion, speed, solar visibility, sect conformity and planetary configurations can alter a planet''s ability to act in a particular figure. These are separate dimensions of accidental condition. Lilly''s *Christian Astrology* (Book I, chapter XVIII) assigns numerical weights to certain conditions, but his scale must not be presumed universal across earlier traditions.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='accidental-fortitude') AND section_key='examples';
UPDATE term_article_sections SET heading='Example: the partner''s resources',body='If the seventh place signifies a partner, the second place counted from the seventh—the radical eighth—can signify that partner''s resources. This is a change of reference within the existing twelve houses, not a relocation of any planet or a second zodiac. The example illustrates the counting rule without making every use of the radical eighth refer to a partner''s property.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='derived-house') AND section_key='reference-shift';
UPDATE term_article_sections SET heading='Exaltation sign and degree in different accounts',body='Al-Bīrūnī (*Book of Instruction*, §443) reports disagreement about the extent of a planet''s exaltation: some astrologers emphasize degrees around its nominated exaltation degree, others a span from the beginning of the sign, and others the entire exaltation sign. Accordingly, a table of exaltation degrees and the sign-wide dignity should not be treated as interchangeable statements.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='exaltation') AND section_key='degree';
UPDATE term_article_sections SET heading='How much of the sign is exalted?',body='The listed exaltation degree identifies a privileged longitude within the exaltation sign, but its practical scope is disputed. Al-Bīrūnī (§443) contrasts exaltation confined to a degree or nearby degrees with broader definitions extending through part or all of the sign. A degree-list records the traditional point without resolving that doctrinal difference.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='exaltation-degree') AND section_key='ontology-distinction';
UPDATE term_article_sections SET heading='A minor dignity that prevents peregrination',body='In Lilly''s treatment, a planet in its own face or decan is not peregrine even when it has no stronger dignity there (*Christian Astrology*, Book I, p. 103; see also p. 112). Face may carry less weight than domicile or exaltation, but it still counts as one of the five essential dignities in his scheme.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='face-decan') AND section_key='minor-dignity';
UPDATE term_article_sections SET heading='The same horizon position can change meaning',body='A diurnal planet above the horizon during a day figure satisfies the horizon-and-sect arrangement described as halb; the same position in a night figure does not. A nocturnal planet follows the opposite pattern. Thus the planet''s sect, the Sun''s location relative to the horizon and the planet''s own location must be assessed together.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='halb') AND section_key='context';
UPDATE term_article_sections SET heading='Lilly''s compound rule for hayz',body='Lilly describes a masculine diurnal planet above the horizon in a masculine sign during the day, and correspondingly a feminine nocturnal planet below the horizon in a feminine sign at night (*Christian Astrology*, Book I, p. 113). In this account hayz therefore combines chart sect, the planet''s position relative to the horizon, and agreement of planet and sign gender. Other authors'' use of hayz and halb must be checked separately.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='hayz') AND section_key='why-compound';
UPDATE term_article_sections SET heading='Lilly''s own-term example',body='Lilly calls a planet peregrine when it has no essential dignity at the relevant degree. His example is Saturn at 10° Aries: it has no dignity there in his adopted scheme, whereas later degrees of Aries fall in Saturn''s own term and therefore prevent peregrination (*Christian Astrology*, Book I, p. 112). The adopted term and face table matters as much as the sign.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='peregrine') AND section_key='recognition';
UPDATE term_article_sections SET heading='Three rulers in al-Bīrūnī''s account',body='Al-Bīrūnī (§445) gives a day ruler, a night ruler and a participating ruler for each triplicity. For the fire signs his three are Sun by day, Jupiter by night and Saturn participating; for the earth signs Venus by day, Moon by night and Mars participating. This is one documented arrangement rather than proof that all historical systems use the same combination.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='triplicity-rulers') AND section_key='variants';
UPDATE term_article_sections SET heading='An alternative way to order the same three',body='Al-Bīrūnī (§445) additionally reports astrologers who assign all three planets to each triplicity simultaneously and change their order for day and night judgments; in fire, the daylight sequence begins Sun, Jupiter, Saturn, while the night sequence begins Jupiter, Sun, Saturn. This describes a difference in how co-rulership is applied, not merely a typographical variation in a table.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='triplicity-rulers') AND section_key='source-variation';
UPDATE term_article_sections SET heading='Example: several classifications at once',body='Aries is simultaneously movable (tropical), fiery, masculine and a sign of short ascension in some northern-latitude schemes. These classifications answer different questions: its place in a seasonal quarter, its elemental triplicity, its alternating gender series and its rising behavior. None replaces the others.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='sign-modality') AND section_key='do-not-collapse';
UPDATE term_article_sections SET heading='Three distinct whole-chart roles',body='The Lord of the Geniture is selected for overall prominence or strength under a particular author''s procedure. A Significator of Manners instead relates to the description of disposition and conduct; Almuten of the Figure names a specialized calculation of chart-wide predominance. The roles may select the same planet in an individual figure without being synonyms.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lord-of-geniture') AND section_key='related-roles';
UPDATE term_article_sections SET heading='A house-based rather than sign-based correspondence',body='Planetary joys belong to the twelve-place framework. The Sun''s joy in the ninth and the Moon''s in the third illustrate how a planetary meaning is related to a house''s topics, independently of whether either luminary is essentially dignified by sign. A joy assignment identifies an accustomed place, not a zodiacal domicile.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='planetary-joy') AND section_key='why-preserve-framework';
UPDATE term_article_sections SET heading='Example of domicile disposition',body='If Mercury occupies Aries, Mars is its domicile dispositor because Mars rules Aries, whether or not Mercury and Mars are in aspect. The same logic can be applied to a lot or other calculated degree within a sign. If a source instead means disposition by exaltation, bound or another dignity, it should name that dignity explicitly.',editorial_notes='Batch 05: source-scoped lexicographic clarification; earlier reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='dispositor') AND section_key='sign-rulership';
